/* Offline usage guide. Keyboard tables use the live bindings instead of a second shortcut list. */
window.LabHelp=(()=>{
  const dialog=$('#help-dialog');
  const example=source=>`<pre><code>${escapeHtml(source)}</code></pre>`;
  const link=(id,label)=>`<a href="#help-${id}">${label}</a>`;
  const environment=[
    ['app','LAB_DATA_DIR','data','Data directory. Relative paths start at the process launch directory; created automatically.'],
    ['server','SERVER_PORT','10081','HTTP listening port.'],['server','SERVER_ADDRESS','127.0.0.1','Listening address; the default is local-only.'],['server','SERVER_SERVLET_CONTEXT_PATH','empty','Optional URL prefix, for example /lab.'],
    ['ai','AI_API_KEY','empty','Provider Bearer token; required by OpenRouter/authenticated providers.'],['ai','AI_MODEL','empty; required for AI','Model ID supported by the provider.'],['ai','AI_API_URL','https://openrouter.ai/api/v1','OpenAI-compatible API base URL or complete chat/completions endpoint.'],
    ['ai','AI_TIMEOUT','300s','Overall model/tool/validation/correction timeout; for example 10m.'],['ai','AI_MAX_TOKENS','128000','Requested output ceiling per response; must fit the model.'],['ai','AI_TOOLS_ENABLED','true','Enable live Java session and library inspection.'],['ai','AI_MAX_TOOL_ROUNDS','16 (1–64)','Inspection rounds before final code generation.'],['ai','AI_MAX_TOOL_CALLS','64 (1–256)','Attempted inspection calls per generation.'],
    ['runtime','JAVA_HOME','launcher dependent','JDK used by build/launch scripts; ensure java on PATH is the intended full JDK 17+.'],['runtime','PATH','operating system','Locates java, Maven, and the Linux xdg-open browser launcher.'],['runtime','JAVA_TOOL_OPTIONS','empty','Standard JVM/tool options; inherited by spawned Java processes.'],['runtime','JDK_JAVA_OPTIONS','empty','Standard java launcher options; inherited by child Java launchers.'],
    ['maven','MAVEN_HOME','unset','Fallback Maven home for conf/settings.xml, after the maven.home Java property.'],['maven','M2_HOME','unset','Older Maven-home fallback, after MAVEN_HOME.'],['maven','MAVEN_OPTS','empty','Maven launcher JVM options for building/running through Maven; not a direct executable-JAR setting.'],
    ['desktop','DISPLAY','desktop session','Linux X11 desktop detection for automatic browser opening.'],['desktop','WAYLAND_DISPLAY','desktop session','Linux Wayland desktop detection; headless servers can open the logged URL manually.']
  ];
  const environmentTable=group=>`<div class="help-table"><table><thead><tr><th>Variable</th><th>Default</th><th>Purpose</th></tr></thead><tbody>${environment.filter(row=>!group||row[0]===group).map(([,name,value,purpose])=>`<tr><td><code>${escapeHtml(name)}</code></td><td>${escapeHtml(value)}</td><td>${escapeHtml(purpose)}</td></tr>`).join('')}</tbody></table></div>`;
  const topics=[
    {id:'overview',title:'Getting started',summary:'Start Java Lab, choose a workspace, and run your first notebook.',content:`
      <h4>Start a local workspace</h4>
      <p>Run Java Lab with a <strong>full JDK 17 or newer</strong> (including JShell). The executable JAR contains the server, editor, charts and data libraries; no frontend build, Python, or CDN is needed.</p>
      ${example('java -jar /path/to/java-lab.jar')}
      <p>The server normally opens your browser at <code>http://127.0.0.1:10081</code>. If it does not, use the address printed in the server log. Add <code>--server.port=8090</code> to use another port.</p>
      <p><strong>The default data directory is {workingDir}/data</strong>, where workingDir is the directory you launch from, not the JAR's directory. It is created automatically. Set <code>LAB_DATA_DIR</code> (or <code>--lab.data-dir=...</code>) to choose another writable data directory; relative settings start at the launch directory. File Browser paths, CSV helpers and relative Java file paths share this data root, including for notebooks in subfolders.</p>
      <p>Existing files are not moved automatically. Set <code>LAB_DATA_DIR=.</code> to continue using the older launch-directory layout. See ${link('configuration','all environment variables and configuration')}.</p>
      <h4>A first notebook</h4>
      <ol><li>Choose <strong>A quick introduction</strong> on the launcher to create and run a fresh guided example.</li>
      <li>Or choose <strong>New notebook</strong>, enter Java snippets in a code cell, and press <strong>Shift + Enter</strong>.</li>
      <li>Add Markdown cells for notes. Use the status bar to see the active mode, selected cell, save state, and kernel state.</li></ol>
      ${example('List<Integer> numbers = List.of(2, 4, 6);\nint total = numbers.stream().mapToInt(Integer::intValue).sum();\nlog("Total = %", total);')}
      <p>You can use <code>numbers</code> and <code>total</code> in later cells without printing them first. AI configuration is optional; notebooks work without it.</p>
      <p><strong>START SOMETHING NEW</strong> also has entries for CSV, JSON, XML, TXT, YAML and SQL files. Choose a filename to create one in the File Browser's current folder; existing names receive a numeric suffix. CSV starts with two placeholder column names, JSON with an empty object, XML with a valid root element, and plain/source files empty. The <strong>Image file</strong> entry uploads an existing image and opens its preview.</p>
      <p>Continue with ${link('files','Files & tabs')}, ${link('execution','Java & sessions')}, or ${link('shortcuts','Keyboard shortcuts')}.</p>`},
    {id:'files',title:'Files & tabs',summary:'Folders, notebooks, CSV tabs, uploads, saving, moving and closing.',content:`
      <h4>File Browser</h4>
      <p>The browser lists <strong>all visible regular files</strong> and supported folders under the configured data directory. File-type icons distinguish notebooks, tables, JSON/XML, text, images, YAML, SQL, configuration, source and archive files. Notebooks and CSVs open their specialized tabs; JSON, XML, TXT and common source/text files open ${link('text','text editor tabs')}; supported images open ${link('images','image preview tabs')}. Other types download when clicked; the context menu also offers <strong>Download file</strong>. Create common formats from the launcher; use <strong>File → New data/text file</strong> for any supported text extension, including Markdown, Java, CSS, HTML, Properties or Log. Hidden paths and symbolic links are excluded. Folder names/uploads are limited to 100 characters, existing file names to 255; folder paths to 10 levels / 500 characters. Do not use path separators inside a single name.</p>
      <ul><li><strong>New notebook</strong> creates a Java notebook in the current folder.</li><li><strong>New folder</strong> creates a subfolder. A folder must be empty before deletion; use its context menu.</li><li><strong>Upload file</strong> accepts data files up to 10 MB. Existing names receive a numeric suffix instead of being overwritten. Notebook import through upload is not supported. CSV uploads open the table editor.</li>
      <li>Rename <strong>any file</strong> through the File Browser context menu or <strong>F2</strong>. For an open file, double-click its tab name, use the tab context menu, click its editor title, or choose <strong>File → Rename file</strong>. Unsaved editable files are saved first; a save failure or name collision keeps the original name. Notebook rename retains its Java kernel and local values. Notebook rows also offer deletion; <strong>Ctrl / Cmd + D</strong> duplicates a notebook.</li></ul>
      <p>Renaming changes the name, not the contents or encoding. Notebook names keep the native <code>.jnb</code> extension (legacy names normalize to it); other extension changes may select another editor. Open tabs follow the new name; Markdown image links, Java source strings and other references to the old path are <strong>not rewritten</strong>. Update them manually, or copy refreshed examples from an image preview.</p>
      <h4>Shared document tabs</h4>
      <p>Notebooks, CSV tables, text files and images share the tab bar. Opening a file again selects its existing tab. Switch by clicking tabs or pressing <strong>Ctrl / Cmd + Shift + [ / ]</strong>. The launcher does not close your open documents. <strong>Ctrl / Cmd + Shift + T</strong> reopens the most recently closed document.</p>
      <p>A dirty dot marks unsaved changes, including on background tabs. <strong>File → Save file</strong> and <strong>Ctrl / Cmd + S</strong> save the active document. Notebook edits autosave after about 1.2 seconds. CSV and text edits are saved explicitly and survive tab switches, together with their position.</p>
      <p>Drag a notebook or CSV onto a folder or <strong>..</strong> to move it. An open document is saved first; moving stops if saving fails. The open tab follows its new path.</p>
      <p>Close a document with its tab's <strong>×</strong>, <strong>File → Close tab</strong>, or <strong>Alt + W / Ctrl + Shift + Q</strong>. Closing a notebook saves it and shuts down its kernel; interrupt a running notebook first. Closing an unsaved CSV/text file asks before discarding edits. CSV/text tabs never create Java kernels.</p>
      <p>Native notebooks use <code>.jnb</code>. Legacy <code>.ipynb</code> files are listed too; renaming/downloading them uses <code>.jnb</code>. Java Lab executes Java, not Python.</p>`},
    {id:'text',title:'Text, JSON & XML files',summary:'Highlighted editor tabs, indentation, format/validate, find and undo.',content:`
      <p>Open or upload a <code>.json</code>, <code>.xml</code> or <code>.txt</code> file to edit it in a document tab. Common text/source extensions (<code>.md</code>, <code>.yaml/.yml</code>, <code>.java</code>, <code>.sql</code>, <code>.properties</code>, <code>.log</code>, <code>.css</code>, <code>.js</code>, <code>.html/.htm</code>) also use this editor. HTML/XML content is displayed as escaped source, never executed.</p>
      <p>Each tab keeps its draft, cursor, scroll position and text undo history. <strong>Save file</strong> or <strong>Ctrl / Cmd + S</strong> writes it; <strong>Reload saved file</strong> reads changes from disk after asking before discarding a draft. A revision conflict keeps your edits. Other/unsupported types are available via download.</p>
      <ul><li>Line numbers and syntax highlighting show the source without reformatting it. Plain TXT stays plain text. Highlighting is reduced to plain text above 300,000 characters.</li><li><strong>Tab / Shift + Tab</strong> indent/outdent; <strong>Enter</strong> keeps indentation and expands structural blocks. Brackets pair automatically, and selections can be wrapped.</li><li><strong>Ctrl / Cmd + Z</strong>, <strong>Ctrl / Cmd + Shift + Z</strong> or <strong>Ctrl + Y</strong> undo/redo typing and assisted edits.</li><li><strong>Ctrl / Cmd + F</strong> focuses file search; Enter/Shift+Enter and the arrow buttons find the next/previous match.</li><li><strong>Format</strong> or <strong>Alt + Shift + F</strong> formats JSON/XML. JSON number spelling, large integers, duplicate keys and key order are preserved. XML formatting preserves mixed content and xml:space; DTD/entities and excessively large/deep structures are not supported by the formatter.</li><li><strong>Validate</strong> reports JSON syntax issues locally; XML uses the server's namespace-aware parser on the <strong>current draft</strong> and reports a line/column when available. Saving first is unnecessary. XML formatting uses the same validation first. This checks well-formedness, not an XSD/schema. DTDs/external entities are disabled. Errors keep the draft; saving incomplete/invalid text is allowed. This is basic edit support, not a language server.</li></ul>
      <p>The editor accepts UTF-8 files up to <strong>2 MB</strong>, preserving BOM and the detected line-ending style. Other encodings/binary content and larger files can be downloaded from the file's context menu. Native Java code can use <code>Files.readString(Path.of("notes.txt"))</code> and <code>Files.writeString(...)</code>; relative paths start at the configured data directory.</p>`},
    {id:'images',title:'Images & embedding',summary:'Image preview tabs, clipboard examples, Markdown images and Java output.',content:`
      <h4>Preview an image</h4><p>Click or upload a PNG, JPEG/JPG, GIF, BMP, WebP or SVG file. The preview opens in a tab, shows format/dimensions/byte size, and provides <strong>Reload</strong> and <strong>Download original</strong>. The launcher's <strong>Image file</strong> entry uploads a file. Preview tabs are read-only and have no Java kernel; rename them like any other file.</p>
      <p>Below the preview are a <strong>Java code cell</strong> example and a <strong>Markdown cell</strong> example, each with a <strong>Copy</strong> button. They use the exact workspace-relative path, including spaces and special characters. If clipboard access is unavailable, select and copy the displayed text directly. Renaming or moving the image refreshes these examples.</p>
      <h4>Use in a Java code cell</h4>${example('Images.show("images/photo.png");')}
      <p><code>Images</code> is pre-imported. <code>show(String)</code> and <code>show(Path)</code> read the file when the cell runs and emit an embedded rich output. <code>Images.show(path, 800, 600)</code> fits the display within those bounds while keeping the aspect ratio. Java image outputs are saved snapshots: they remain available after reopening/exporting even if the original file later moves. Rerun the cell to update them.</p>
      <h4>Use in a Markdown cell</h4>${example('![Description](<images/photo.png>)')}
      <p>Paths are relative to the <strong>configured data root</strong>, not the notebook's subfolder. The preview's copied example percent-encodes special characters. Markdown resolves images through the workspace image endpoint; external URLs, data/file URLs, hidden paths and parent traversal are not supported. Missing files show an unavailable-image message. Markdown images read the current file; they are not embedded into the notebook source, so distribute referenced files when sharing a notebook.</p>
      <p><strong>Export HTML</strong> embeds referenced Markdown image files as data images for offline viewing, in addition to existing Java image outputs. Missing/invalid assets stop the export rather than silently leaving server links. Export supports up to 100 referenced images / 32 MB of encoded Markdown assets.</p>
      <p>Limits: 10 MB per image, 10,000 pixels per side / 40 million pixels; Java outputs share the 16-display / 16 MB per-snippet budget. SVG is loaded as an image, not inserted as active DOM markup; DTD/external entities are rejected and preview responses restrict active/external content. Changing an extension only renames a file; it does not convert the image format.</p>`},
    {id:'configuration',title:'Configuration & environment',summary:'Data directory, server, AI, Java, Maven and desktop environment variables.',content:`
      <h4>Choose the data directory</h4>
      <p>By default, files live under <code>{workingDir}/data</code>. Set <code>LAB_DATA_DIR</code> or <code>--lab.data-dir=...</code> to override it. The directory is created at startup. Relative values resolve against the launch directory; use an absolute path when launching from different locations. Shell expansion such as <code>$HOME</code> happens in the shell; Java does not expand a literal tilde.</p>
      ${example('LAB_DATA_DIR="$HOME/java-lab-files" java -jar /path/to/java-lab.jar\n# Keep the previous working-directory layout:\nLAB_DATA_DIR=. java -jar /path/to/java-lab.jar')}
      <p>The File Browser, notebooks, uploads, text/CSV editors, AI CSV catalog and relative Java NIO Path/Files and CSV helper operations use this same data directory. For legacy java.io APIs, pass <code>Path.of(...).toAbsolutePath().toFile()</code>; give native child processes an explicit working directory. Existing files are not automatically relocated. Local notebook values are kept in <code>.java-lab-values</code> beside the chosen data root and are associated with the absolute notebook path.</p>
      <h4>Environment variable reference</h4><p>Set variables in the process launching Java Lab, then restart it. Defaults below are application defaults, not a display of current secrets or runtime values.</p>
      ${environmentTable()}
      <p><strong>Notebook environment bindings</strong> may name additional variables of your choice, such as <code>JDBC_URL</code> or <code>API_TOKEN</code>. They have no global Java Lab default; configure them in notebook Settings. Maven settings can similarly reference arbitrary <code>env.NAME</code> placeholders and environment activation conditions. These user-defined names cannot be enumerated in a fixed list.</p>
      <p>Spring Boot also supports its standard external configuration and relaxed property-to-environment binding; the server variables above are the common supported controls. Command-line properties such as <code>--lab.data-dir=...</code>, <code>--server.port=8090</code> and <code>--lab.ai.timeout=10m</code> override environment settings. <code>JAVA_HOME</code>, JVM options, Maven options and desktop variables are launcher/runtime conventions, not notebook settings. See ${link('ai-setup','AI setup & diagnostics')} for provider examples and failure recovery.</p>`},
    {id:'editing',title:'Cells & editing',summary:'Code, Markdown, selections, cell operations, completion and search.',content:`
      <h4>Cell types and modes</h4>
      <p><strong>Code</strong> cells contain Java snippets. <strong>Markdown</strong> cells contain formatted notes; double-click the preview for split editing/live preview, then use <strong>Done</strong> or run the cell to render it. Headings, lists, tables, links and fenced code are supported. <strong>Raw</strong> cells keep unexecuted text.</p>
      <p><strong>Escape</strong> enters notebook command mode; <strong>Enter</strong> edits the active cell. Command-mode letters apply to cells, while regular typing in editors and form fields stays text. The status bar shows the mode.</p>
      <h4>Links in Markdown cells</h4>
      ${example('[Website](https://example.com "Optional title")\n[E-mail](mailto:help@example.com)\n[CSV data](<Data/sales 2026.csv>)\n[Picture preview](opencode.png)\n[Results](#results)\n\n## Results')}
      <p>Web links open a new tab; mail links open the configured mail application. Workspace file links start at the configured data root and open the matching notebook/CSV/text/image tab, or download unsupported types. Use angle brackets or percent encoding for paths with spaces; <code>./</code> is accepted. Section links use lower-case heading words separated by hyphens; repeated headings get suffixes such as <code>-1</code>. Expand a folded section before jumping into it. Unsafe protocols, hidden paths and parent traversal are not supported. Link-looking text inside inline/fenced code remains code.</p>
      <p>In exported HTML, web/mail and section links remain functional. Workspace file links become relative links, so distribute those referenced files alongside the HTML at the expected paths. Markdown images are embedded separately; see ${link('images','Images & embedding')}.</p>
      <h4>Arrange and reuse cells</h4>
      <p>Use cell action buttons and the <strong>Edit</strong> menu to insert, duplicate, move, delete, merge or split cells. Shift-click a cell prompt/output, or use <strong>Shift + ↑ / ↓</strong> in command mode, to extend a selection. Multi-cell runs follow document order and stop at the first error.</p>
      <p><strong>X / C / V</strong> cut, copy and paste cells in command mode. The cell clipboard can be used across notebook tabs in the same browser session. <strong>Z / Shift + Z</strong> undo/redo cell operations. These are separate from native text undo; cell clipboard and undo history are not stored in the notebook file.</p>
      <p>Heading controls collapse sections. The <strong>View</strong> menu and shortcuts toggle line numbers, hidden/scrolled outputs, and side-by-side layout. Notebook source search uses <strong>Ctrl / Cmd + F</strong>, replace uses <strong>Ctrl / Cmd + H</strong>, and <strong>Ctrl / Cmd + G</strong> moves through matches. Search covers code, Markdown and raw source, not saved outputs or other files.</p>
      <h4>Java completion and signatures</h4>
      <p>Completion appears after a pause while typing; <strong>Ctrl + Space</strong> requests it explicitly. Select with arrow keys, accept with <strong>Enter / Tab</strong>, and dismiss with <strong>Escape</strong>. <strong>Shift + Tab</strong> after code inspects signatures; elsewhere it outdents. Definitions/imports must have been executed into the current idle session for session-aware suggestions.</p>
      <p><strong>Ctrl / Cmd + Shift + C</strong> opens the command palette. ${link('shortcuts','The complete shortcut reference')} includes indentation, comments, execution history, selection, folding and cell-type shortcuts.</p>`},
    {id:'execution',title:'Java & sessions',summary:'Run controls, reusable variables, outputs, reset, interruption and limits.',content:`
      <h4>Run snippets, not an application</h4>
      <p>A <code>main</code> method or wrapping application class is unnecessary. Imports, variables, methods and classes declared at the top JShell level remain available to later cells in that notebook. Keep reusable results at top level; variables inside a block, method or lambda stay local to it. Values do not need to be printed to remain available.</p>
      <p>Preloaded imports include <code>java.util.*</code>, <code>java.util.stream.*</code>, <code>java.time.*</code>, <code>java.nio.file.*</code>, bundled JSON/CSV/chart imports, and the <code>Csv</code>, <code>Images</code>, <code>Charts</code>, <code>ECharts</code>, <code>Grid</code>, <code>Formatted</code> and <code>Forms</code> helpers. Add only imports you still need.</p>
      <ul><li><strong>Ctrl / Cmd + Enter</strong>: run selected cells.</li><li><strong>Shift + Enter</strong>: run and advance; at the end, create another cell.</li><li><strong>Alt + Enter</strong>: run and insert a cell below.</li><li><strong>Run all</strong>: run in order, stopping on the first error.</li><li><strong>Interrupt kernel</strong>: stop current execution and pending multi-cell work.</li><li><strong>Restart kernel</strong>: reset the Java session. <strong>Restart & run all</strong> reconstructs it from notebook source.</li></ul>
      <h4>Session lifetime and recovery</h4>
      <p>Each open notebook has its own Java kernel in a separate JVM; CSV tabs have none. Saved source and outputs survive closing/restarting, but <strong>live Java objects do not</strong>. Browser refresh, closing a notebook, applying changed settings, or restarting the server/kernel requires rerunning definition cells. Idle kernels expire after one hour. Use <strong>Restart & run all</strong> after reconnecting or when state and saved outputs no longer agree.</p>
      <p>Re-running or interrupting code may leave partial state changes; output clearing is not a session reset. Compilation/runtime diagnostics appear below the cell. The failed snippet stops the rest of that cell. If a kernel cannot start, correct its variables/libraries in <strong>Settings</strong>, then choose <strong>Apply & restart kernel</strong>.</p>
      <h4>Text results and logging</h4>
      <p>The last statement's value is displayed automatically; intermediate results stay quiet. Chart/table values use rich renderers. Explicit <code>show()</code>, console and log output appear where called. <code>log</code> uses literal <strong>%</strong> placeholders, not printf's <code>%s</code> or <code>%d</code>:</p>
      ${example('log("Hello %, total = %", "Ada", total);')}
      <p>Limits: 30 seconds per cell, 100,000 source characters per cell, 1 MB captured per console stream between snippets, and 32 active kernels. Java code runs with your local user's filesystem/process permissions; it is not a sandbox. Console input is not implemented.</p>`},
    {id:'csv',title:'CSV files & helper',summary:'Edit CSV tabs and load/save reusable CSV data from Java.',content:`
      <h4>Edit a CSV tab</h4>
      <p>Open a CSV from the File Browser or upload one. Edit all records, including the first; add/delete records or columns with the table buttons. Pages contain 50 records. Switching tabs keeps each draft, page and scroll position. Save with <strong>Save CSV</strong>, <strong>File → Save file</strong> or <strong>Ctrl / Cmd + S</strong>.</p>
      <p>Files use UTF-8. Comma, semicolon, tab and pipe are auto-detected. If detection is ambiguous, select <strong>Read delimiter</strong> to reload the saved file with an explicit delimiter. <strong>Reload saved file</strong> reads changes made by notebook code or another editor. Both reload and closing ask before discarding a draft.</p>
      <p>Saving preserves values such as <code>001</code>, empty cells, quotes and embedded newlines, the UTF-8 BOM, detected line endings, and a final newline when present. CSV quoting is normalized; original byte-for-byte formatting is not retained. If the file changed on disk, saving reports a conflict and keeps your draft. Copy any needed edits before confirming a reload.</p>
      <h4>Load and save from Java</h4>
      ${example('var salesCsv = Csv.load("Data/sales.csv");\nvar salesRecords = salesCsv.records();\nCsv.save("Data/sales-copy.csv", salesCsv);')}
      <p><code>Csv</code> is pre-imported. Paths start at the <strong>workspace root</strong>, not at the notebook's subfolder. The parent folder must exist when saving. Use <code>Csv.load(path, \';\')</code> to select a delimiter explicitly.</p>
      <ul><li><code>rows()</code> includes every record, including the first.</li><li><code>headers()</code> returns the first record; <code>data()</code> returns all remaining records.</li><li><code>records()</code> returns string-valued maps, treating the first record as headers. Headers must be unique/nonblank and record widths must match. For headerless or ragged files, use <code>rows()</code>.</li><li>Tables, rows and record maps are immutable. Copy rows to edit them, then create a table with <code>withRows(...)</code>. Convert numeric strings explicitly for numeric calculations or sorting.</li></ul>
      ${example('var editedRows = salesCsv.rows().stream()\n    .map(row -> new ArrayList<>(row)).toList();\n// Edit copied cells as needed before saving.\nvar editedCsv = salesCsv.withRows(editedRows);\nCsv.save("Data/sales-edited.csv", editedCsv);')}
      <p>A table result displays a compact dimensions summary; rows remain available to later cells and AI session inspection without being printed. Saving a file does not refresh objects already loaded in Java: rerun the loading cell to read the new data. The helper/editor support 10 MB, 10,000 records including the first, 100 columns, 100,000 cells, and 100,000 characters per cell. For larger files, use the bundled Apache Commons CSV streaming API.</p>
      <h4>CSV context for Vibecode</h4>
      <p>The AI knows saved visible workspace CSV paths, sizes, detected delimiters and bounded first-record column names, even if preceding-cell context is off. Subsequent data rows and unsaved CSV drafts are not included automatically. The first record is assumed to be a header; use <code>rows()</code> for headerless input. The catalog is bounded to 50 files/about 24,000 characters and 20 column names of 80 characters per file, with omissions reported. Save edits before asking the AI to use them.</p>`},
    {id:'settings',title:'Variables & libraries',summary:'Notebook settings, credentials, Maven dependencies and JDBC.',content:`
      <h4>Notebook variables</h4>
      <p>Open a Java notebook, then use <strong>Settings</strong> or <strong>File → Notebook settings</strong>. Define a name, optional shareable default, optional environment-variable binding, and optional local value. Resolution is <strong>local value → environment variable → notebook default</strong>.</p>
      ${example('String endpoint = requireLabVar("API_URL");\nString token = labVar("API_TOKEN");\nlog("Credentials configured: %", token != null);')}
      <p><code>labVar(name)</code> returns null when unset; <code>requireLabVar(name)</code> fails clearly. Mark credentials as <strong>secret</strong>: they cannot have a notebook default. Definitions and non-secret defaults are saved in the notebook. Personal overrides are stored separately in a <code>.java-lab-values</code> directory beside the workspace, not in the notebook; the settings API does not reveal secret values. Use the clear-local-value control to fall back to an environment variable/default.</p>
      <p><strong>Apply & restart kernel</strong> installs changed variables/libraries into a fresh Java session. Rerun cells afterwards. Cancel leaves unapplied settings alone. Notebook code can still read or print credentials, so do not put their literal values in source or outputs intended for sharing.</p>
      <h4>Additional Maven libraries</h4>
      <p>Add exact <code>groupId:artifactId:version</code> coordinates, for example <code>org.apache.commons:commons-lang3:3.17.0</code>. Java Lab downloads transitive runtime dependencies and adds them only to this notebook's kernel. Applying changes restarts that kernel; imported classes and earlier definitions must be reconstructed.</p>
      <p>Maven Central is used by default. For private repositories, mirrors, proxies, authentication, offline mode and a custom local cache, configure Maven's <code>~/.m2/settings.xml</code>; keep repository passwords there, not in the notebook. Active profile repositories and property/environment activation are supported; JDK/OS/file profile activation is not.</p>
      <h4>Database connections</h4>
      <p>For JDBC, add your database driver's exact Maven coordinate and define the connection URL/user/password in notebook variables. Import <code>java.sql.*</code> if needed. A connection is a live resource, not saved session state; close short-lived connections, statements and result sets with try-with-resources. Database schema and row values are not automatically queried by the AI's Java session-inspection tools. Run metadata/sample queries yourself and keep useful results in session variables or include their textual output as context.</p>
      <p>Missing library/class errors usually require checking coordinates and reapplying settings. Authentication/download errors require checking Maven repository settings; missing notebook values require supplying a local value, environment binding or default.</p>`},
    {id:'charts',title:'Charts & tables',summary:'JFreeChart, ECharts and Grid.js examples, interaction and limits.',content:`
      <h4>Interactive charts with ECharts</h4>
      <p>ECharts 6.0.0 is bundled, including its offline browser runtime. Use the pre-imported Java wrapper with Java lists, arrays, numbers and maps:</p>
      ${example('ECharts.chart().title("Revenue")\n    .categories("Jan", "Feb", "Mar")\n    .bar("Sales", 12, 19, 15)\n    .series(ECharts.lineSeries("Target", 15, 17, 19).smooth())\n    .legend(true).tooltipAxis().show();')}
      <p>Use <code>line</code>, <code>bar</code>, <code>scatter</code> or <code>pie</code>, <code>size(width, height)</code>, <code>zoom()</code>, axis/title options, and styled series such as <code>stack</code>, <code>smooth</code> and <code>area</code>. <code>option(key, value)</code> accepts ordinary Java maps/lists/arrays. <code>toOption()</code> and <code>toJson()</code> help inspect options. JavaScript callbacks are not supported. Legends and hover tooltips work in notebooks and exported HTML.</p>
      <h4>PNG charts with JFreeChart</h4>
      <p>JFreeChart 1.5.6 and common chart/data imports are bundled. The kernel is headless; use <code>Charts.show</code> instead of Swing windows.</p>
      ${example('var chartData = new DefaultCategoryDataset();\nchartData.addValue(12, "Sales", "Jan");\nchartData.addValue(19, "Sales", "Feb");\nvar chart = ChartFactory.createBarChart("Sales", "Month", "Value", chartData);\nCharts.show(chart);')}
      <p><code>Charts.show(chart, width, height)</code> changes the default 900 × 520 size. A final JFreeChart or ECharts chart value is also rendered automatically. Saved PNG/interactive outputs survive reopening a notebook.</p>
      <h4>Searchable tables with Grid.js</h4>
      ${example('Grid.table().title("Sales").columns("Month", "Revenue")\n    .row("Jan", 12).row("Feb", 19)\n    .search(true).sortable(true).pagination(10).show();')}
      <p>Use <code>Grid.fromRecords(records)</code> for maps, or explicit columns/rows for controlled ordering. Columns can set ids, widths and sorting. Values are plain text, numbers, booleans or null; convert dates/objects yourself. Numeric values sort numerically; CSV strings do not become numbers automatically. This output table is a viewer, while ${link('csv','CSV tabs')} are editable file tables. JavaScript callbacks and server-backed Grid data are not supported.</p>
      <p>Chart dimensions are 100–2400 pixels per side, at most 4 million pixels. Charts/tables share a limit of 16 rich displays / 16 MB per Java snippet. Grid supports 10,000 rows, 1,000 columns, 1–1,000 rows per page and 1,000,000 serialized characters; interactive chart options are limited to 1,000,000 characters. ${link('export','HTML export')} embeds the required runtimes for offline use.</p>`},
    {id:'forms',title:'Forms & formatted data',summary:'Interactive inputs, stale outputs, JSON/XML explorers and data libraries.',content:`
      <h4>Interactive form inputs</h4>
      ${example('Forms.form("preferences")\n    .text("name", "Name", "Ada").required("name")\n    .number("threshold", "Threshold", 10).range("threshold", 0, 100)\n    .select("role", "Role", "reader", "admin")\n    .checkbox("enabled", "Enabled", true).show();')}
      <p>Other controls include textarea, email, date and multiselect. Use distinct field ids across the notebook; ids start with a letter and may contain letters, numbers, underscore, dot and dash (up to 100 characters). Read values in later cells:</p>
      ${example('String name = Forms.text("name");\ndouble threshold = Forms.number("threshold");\nboolean enabled = Forms.bool("enabled");')}
      <p><code>Forms.value</code> returns a raw value and <code>Forms.list</code> reads selections. After editing a form, choose <strong>Apply values & run following cells</strong>. Validation prevents invalid values from reaching later execution. Existing dependent outputs are marked stale until rerun. Values are synchronized before later cells run and are saved with the notebook. After a kernel restart, rerun definition/form cells; saved form output is not a live Java session.</p>
      <p>Forms support 100 fields per form, 200 synchronized values / 100 KB per execution request, within the shared rich-display limit. Exported forms show saved values but cannot execute Java.</p>
      <h4>Readable JSON, YAML, XML and source output</h4>
      ${example('Formatted.prettyJson("{\\"name\\":\\"Ada\\",\\"active\\":true}");\nFormatted.prettyYaml("person: {name: Ada, active: true}");\nFormatted.prettyXml("<person><name>Ada</name></person>");\nFormatted.show("sql", "select * from people;");')}
      <p><code>Formatted.show(format, text)</code> preserves text with highlighting; <code>prettyJson</code>, <code>prettyYaml</code> and <code>prettyXml</code> validate/reformat it. Supported formats include JSON, YAML, XML, HTML, CSS, JavaScript, Java, SQL, Markdown, CSV and text. Source is displayed as text, not executed as HTML/JavaScript. Invalid input reports an error; YAML formatting can discard comments.</p>
      <p>JSON/XML outputs also have an expandable tree. Use <strong>Copy</strong> or <strong>Download</strong> to obtain the source. Structured output remains available in saved notebooks and HTML exports.</p>
      <h4>Bundled parsing libraries</h4>
      <p><code>org.json.*</code> and <code>org.apache.commons.csv.*</code> are pre-imported. Parse JSON with <code>new JSONObject(jsonText)</code>/<code>new JSONArray(jsonText)</code>, bridge with <code>toMap()</code>/<code>toList()</code>, and pretty-print with <code>toString(2)</code>. Use <code>JSONObject.NULL</code> for JSON null. Commons CSV handles quoted delimiters/newlines and UTF-8 BOM input with <code>BOMInputStream</code>; never split CSV using <code>String.split</code>. For convenient file tables see ${link('csv','Csv.load / Csv.save')}.</p>`},
    {id:'ai',title:'Vibecode & AI context',summary:'Generate/edit cells, fix errors, inspect live state, undo and control context.',content:`
      <h4>Generate an edit</h4>
      <ol><li>Select a Java code cell. Optionally select the exact text to replace in its editor.</li><li>Choose <strong>✦ Vibecode</strong> or press <strong>Alt + Shift + V</strong>.</li><li>Describe the change. Choose whether to include preceding cells/outputs and add requirements or API notes under <strong>Additional context</strong>.</li><li>Choose <strong>Generate & apply</strong>. The replacement is saved, but <strong>not executed</strong>; run it with the normal controls.</li></ol>
      <p><strong>Undo AI edit</strong> on the cell restores its previous source and outputs. It is session-local and will not overwrite later manual source changes. Applying an AI edit clears that cell's old outputs. A late response is discarded if its target changed or its kernel was replaced.</p>
      <p>After a Java cell fails, <strong>✦ Fix with AI</strong> sends the complete cell and its diagnostics, immediately requests a correction, and applies it without executing it. Undo restores the failed cell and its outputs.</p>
      <h4>What the model can use</h4>
      <ul><li>The target source, instruction, optional notes and current-cell errors.</li><li>When enabled, preceding cell source and bounded saved text/Grid output. Images and large chart payloads are excluded.</li><li>Java runtime details and the bundled library/helper APIs.</li><li>Notebook variable definitions and Maven coordinates; local/resolved settings values are not included in that settings context.</li><li>Saved workspace CSV paths and bounded first-record column names, even with preceding-cell context off.</li></ul>
      <p>With an idle live kernel and tools enabled, the model can list variables/types, imports, methods and libraries; read current values; descend into private/inherited fields where Java permits, arrays, collections and maps; and search loaded library classes/APIs. Values do not need to be printed first. Inspections are structured and bounded; arbitrary expressions, getters and object <code>toString()</code> methods are not evaluated. Inaccessible fields/cycles are marked. Variable pages contain up to 25 children, scalar previews up to 1,000 characters, paths up to 16 steps, and class/API pages up to 40 entries. Code edits do not update live values until executed.</p>
      <p>Turning off preceding-cell context does <strong>not</strong> turn off live inspection or CSV metadata. Set <code>AI_TOOLS_ENABLED=false</code> at server startup to disable session tools. Known configured secret values are masked in tool results; ordinary inspected session data and explicitly included code/notes/outputs are sent to the configured provider.</p>
      <h4>Progress and response checking</h4>
      <p>Hover or keyboard-focus <strong>Generating code…</strong> for live requests/tool activity and token diagnostics. Escape dismisses that popup alone. These are activity summaries, not internal model thoughts. Cancel stops applying the response; server/provider work may still finish.</p>
      <p>The prompt prefers reusable top-level variables, existing definitions, missing imports only, and no redundant logic. Before applying, Java syntax/completeness is checked on the resulting whole cell. A truncated/incomplete response gets <strong>one correction attempt</strong> using the remaining timeout. If it still fails, source and outputs are kept. This is not a type, database-schema or runtime correctness check. See ${link('ai-setup','AI setup & diagnostics')}.</p>`},
    {id:'ai-setup',title:'AI setup & diagnostics',summary:'Provider configuration, timeout/token budgets, inspection limits and recovery.',content:`
      <h4>Configure the server process</h4>
      <p>Use an OpenAI-compatible Chat Completions provider and its supported model ID. OpenRouter is the default; authentication-free local providers may omit the key. Replace the placeholders in this macOS/Linux shell example. On Windows, set the same environment variables in the process launching Java Lab:</p>
      ${example('export AI_API_URL="https://openrouter.ai/api/v1"\nexport AI_MODEL="provider/model-id"\nexport AI_API_KEY="YOUR_KEY"\nexport AI_TIMEOUT="10m"\njava -jar java-lab.jar')}
      <p><code>AI_API_URL</code> is the API base URL, including prefixes such as <code>/v1</code>. A complete <code>/chat/completions</code> endpoint is also accepted. For example, a local compatible server can use <code>http://localhost:11434/v1</code>. Credentials stay in the server process. Restart Java Lab after changing these settings; browser/notebook settings do not configure the global AI provider. For older configurations, rename <code>OPENROUTER_API_KEY</code> / <code>OPENROUTER_MODEL</code> to <code>AI_API_KEY</code> / <code>AI_MODEL</code>.</p>
      ${environmentTable('ai')}
      <p>For the data directory, server, Java/Maven and desktop variables, see ${link('configuration','the complete environment reference')}.</p>
      <p>The equivalent Spring options include <code>--lab.ai.timeout=10m</code>, <code>--lab.ai.max-tokens=16384</code>, <code>--lab.ai.max-tool-rounds=24</code> and <code>--lab.ai.max-tool-calls=96</code>. The separate Java cell timeout stays 30 seconds; inspection calls have a 5-second limit and connection establishment a 10-second limit.</p>
      <h4>Read the diagnostics first</h4>
      <p>The Live activity popup shows configured/reported model IDs, requested output token limit, <code>finish_reason</code>, and provider-reported input/output/reasoning tokens per request. Missing data says <strong>not reported</strong>, not zero. Reasoning tokens may already be included in output totals. After an error, <strong>Last generation diagnostics</strong> expands below it; after success, reopen Vibecode on that cell to read its last diagnostics. This history is not stored in notebook files.</p>
      <ul><li><strong>Timeout:</strong> increase <code>AI_TIMEOUT</code>, choose a faster model, or reduce irrelevant preceding-cell context. Tool rounds share one overall budget. A local increase cannot change the provider/proxy's own timeout.</li>
      <li><strong>Cannot connect:</strong> check the API URL, network and provider availability. Authentication, payment and rate-limit errors have separate messages.</li>
      <li><strong>Rejected request:</strong> check model ID, endpoint and the model's supported output ceiling; reduce <code>AI_MAX_TOKENS</code> if needed. For models without tools, disable <code>AI_TOOLS_ENABLED</code>.</li>
      <li><strong>Inspection budget:</strong> the server ends inspection and asks once for final code without tools. It may then make its single correction attempt. Raise tool budgets only for genuinely involved edits; they do not reset the timeout.</li>
      <li><strong>Truncated/broken output:</strong> inspect the finish reason and usage. <code>length</code> or malformed Java causes one correction; a second failure keeps your original cell. Input, tool history, output and sometimes reasoning share model-specific limits, so a larger output ceiling alone is not a general fix.</li>
      <li><strong>Too much context:</strong> include fewer preceding cells/notes or make a focused selection edit. Source/replacement cells are limited to 100,000 characters; combined reference context to 200,000; accumulated tool data to 120,000. Individual tool results are capped at 24,000 characters.</li></ul>`},
    {id:'export',title:'Export & sharing',summary:'HTML reports, share-safe notebooks, saved values and offline use.',content:`
      <h4>Standalone HTML reports</h4>
      <p>Use <strong>Export HTML</strong> or <strong>File → Export as HTML (with outputs)</strong> on a notebook. It saves the notebook first, then exports saved source, Markdown and outputs; it does not run cells. The document includes styling, chart images and the runtimes required for saved ECharts/Grid outputs, so it opens offline with interactive legends, tooltips, table search, sorting and pagination. Use the browser's print function for a paper/PDF view.</p>
      <p>Saved forms appear with their current values but cannot execute Java or rerun dependent cells in exported HTML. Unsupported rich output types and arbitrary live Java session objects are not exported.</p>
      <h4>Share-safe notebook download</h4>
      <p><strong>File → Download share-safe notebook (.jnb)</strong> removes cell outputs, execution counts and saved form values from the download. It keeps code, Markdown, other metadata, variable definitions/non-secret defaults and Maven dependencies. The working copy is not cleared. Local credential overrides remain outside notebook documents.</p>
      <p>Review source, notes and non-secret defaults before sharing; they can contain values you entered directly. HTML includes saved output/form values and embedded referenced Markdown images. CSV and other data files remain separate, and notebooks keep Markdown image paths rather than file bytes; distribute referenced files separately when sharing the notebook itself.</p>
      <h4>Reconstructing a shared notebook</h4>
      <p>The receiver needs a full JDK and Java Lab, the referenced data files in the expected workspace-relative paths, any required notebook/environment variables, and access to configured Maven repositories or cached dependencies. Open the notebook, supply local values in Settings, and use <strong>Restart & run all</strong>. Saved output is a prior presentation, not proof that the new Java session has run those cells.</p>`},
    {id:'shortcuts',title:'Keyboard shortcuts & about',summary:'The complete live shortcut reference, modes, command palette and project links.',content:`
      <p><strong>Ctrl / Cmd</strong> means Control on Windows/Linux and Command on macOS; explicit accelerators also accept Control on macOS. Native textarea movement/selection/clipboard follow your OS. Browser-reserved keys work only when delivered to the app.</p>
      <p><strong>Escape</strong> enters notebook command mode; <strong>Enter</strong> edits a cell. Single-letter actions apply in command mode, not while entering text. Double-key sequences such as <strong>D D</strong>, <strong>I I</strong> and <strong>0 0</strong> require separate presses within one second. Cell undo and native text undo are different histories.</p>
      <p><strong>Ctrl / Cmd + Shift + H</strong>, or <strong>H / ?</strong> in notebook command mode, opens this reference. The table below is generated from the application's current shortcut definitions.</p>
      <div id="help-shortcut-list"></div>
      <h4>About Java Lab</h4><p>A local Java notebook workspace built with Spring Boot and JShell. Notebooks, CSV files, bundled data libraries, charts, tables and this help work without a CDN. AI requests and uncached Maven dependency downloads use their configured services. A full JDK 17+ is required.</p>
      <p>Controls follow JupyterLab 4.6 notebook defaults with classic Notebook aliases; this is not a full Vim keymap or a Jupyter kernel installation. <a href="https://github.com/software-atelier/java-lab" target="_blank" rel="noopener noreferrer">Project and README</a> · <a href="https://github.com/software-atelier/java-lab/blob/main/KEYBOARD_SHORTCUTS.md" target="_blank" rel="noopener noreferrer">Shortcut reference</a> · <a href="https://jupyterlab.readthedocs.io/en/stable/user/commands.html" target="_blank" rel="noopener noreferrer">JupyterLab command reference</a></p>`}
  ];
  let selected='overview',opener=null;
  const shortcuts=()=>window.NotebookControls?.shortcuts||[];
  function matchingTopics(){
    const words=$('#help-search').value.toLowerCase().trim().split(/\s+/).filter(Boolean);
    return topics.filter(topic=>{
      const text=[topic.title,topic.summary,topic.content.replace(/<[^>]*>/g,' '),topic.id==='shortcuts'?shortcuts().flat().join(' '):''].join(' ').toLowerCase();
      return words.every(word=>text.includes(word));
    });
  }
  function renderNavigation(){
    const matches=matchingTopics();
    $('#help-topics').innerHTML=matches.length?matches.map(topic=>`<button type="button" data-help-topic="${topic.id}" ${topic.id===selected?'aria-current="page"':''}><strong>${escapeHtml(topic.title)}</strong><span>${escapeHtml(topic.summary)}</span></button>`).join(''):'<p class="help-empty">No matching topics. Try a feature name, helper method, or shortcut.</p>';
    $('#help-result-count').textContent=`${matches.length} of ${topics.length} topics`;
  }
  function showTopic(id){
    const topic=topics.find(item=>item.id===id)||topics[0];selected=topic.id;
    $('#help-topic-title').textContent=topic.title;$('#help-topic-body').innerHTML=topic.content;
    if(topic.id==='shortcuts'){
      const headings={Both:'Running cells — either mode',Command:'Notebook command mode',Edit:'Notebook edit mode',Application:'Application & tabs','File browser':'File browser','Text editor':'Text file editor'};
      $('#help-shortcut-list').innerHTML=Object.entries(headings).map(([group,title])=>
        `<section><h4>${escapeHtml(title)}</h4>`+shortcuts().filter(row=>row[0]===group).map(([,keys,label])=>`<div class="shortcut-row"><span>${escapeHtml(label)}</span><kbd>${escapeHtml(keys)}</kbd></div>`).join('')+'</section>').join('');
    }
    renderNavigation();$('#help-content').scrollTop=0;$('#help-topic-title').focus({preventScroll:true});
  }
  function open(id='overview'){
    if(!dialog.open){
      const focused=document.activeElement;
      opener=focused?.closest?.('.menu')?.querySelector('.menu-trigger')||focused;
      dialog.showModal();
    }
    $('#help-search').value='';showTopic(id);
  }
  function close(){dialog.close();if(opener?.isConnected)opener.focus();opener=null;}
  $('#help-search').addEventListener('input',renderNavigation);
  $('#help-topics').addEventListener('click',event=>{const id=event.target.closest('[data-help-topic]')?.dataset.helpTopic;if(id)showTopic(id);});
  $('#help-topic-body').addEventListener('click',event=>{
    const anchor=event.target.closest('a[href^="#help-"]');if(!anchor)return;
    event.preventDefault();$('#help-search').value='';showTopic(anchor.getAttribute('href').slice(6));
  });
  $('#help-close').onclick=close;$('#help-done').onclick=close;
  dialog.addEventListener('cancel',event=>{event.preventDefault();close();});
  for(const topic of topics)actions[topic.id==='overview'?'help':`help-${topic.id}`]=()=>open(topic.id);
  return {open,close};
})();
